  // ============================================================
  // MENU
  // ============================================================

  const toggle =
    $(".nav-toggle");

  const menu =
    $("#menu");


  toggle.addEventListener(
    "click",
    () =>
      toggle.setAttribute(
        "aria-expanded",
        menu.classList.toggle(
          "open"
        )
      )
  );


  // ============================================================
  // AVISOS
  // ============================================================

  const toast =
    $("#toast");

  let toastTimer;


  function aviso(txt) {

    toast.textContent =
      txt;

    toast.hidden =
      false;

    clearTimeout(
      toastTimer
    );


    toastTimer =
      setTimeout(
        () => {

          toast.hidden =
            true;

        },
        4000
      );

  }


  const links =
    [
      ...menu.querySelectorAll(
        "a[data-menu]"
      )
    ];


  const secoes = {

    mapa:
      $("#mapa"),

    especies:
      $("#especies")

  };


  let travado = false;

  let travaTimer;

  let raf;


  function marcar(chave) {

    links.forEach(
      (l) => {

        const on =
          l.dataset.menu ===
          chave;


        l.classList.toggle(
          "active",
          on
        );


        if (on) {

          l.setAttribute(
            "aria-current",
            "page"
          );

        }

        else {

          l.removeAttribute(
            "aria-current"
          );

        }

      }
    );

  }


  function destacar(chave) {

    const t =
      secoes[
        chave
      ].querySelector(
        ".h2"
      );


    t.classList.remove(
      "destaque"
    );


    void t.offsetWidth;


    t.classList.add(
      "destaque"
    );

  }


  function atualizarMenu() {

    if (travado) return;


    const linha =
      window.innerHeight *
      0.35;


    const m =
      secoes.mapa
        .getBoundingClientRect();


    marcar(
      m.top <= linha &&
      m.bottom > linha
        ? "mapa"
        : "especies"
    );

  }


  window.addEventListener(
    "scroll",
    () => {

      cancelAnimationFrame(
        raf
      );


      raf =
        requestAnimationFrame(
          atualizarMenu
        );

    },
    {
      passive: true
    }
  );


  menu.addEventListener(
    "click",
    (e) => {

      const a =
        e.target.closest(
          "a[data-menu]"
        );


      if (!a) return;


      const chave =
        a.dataset.menu;


      menu.classList.remove(
        "open"
      );


      toggle.setAttribute(
        "aria-expanded",
        "false"
      );


      if (
        secoes[chave]
      ) {

        e.preventDefault();

        marcar(chave);

        travado = true;

        clearTimeout(
          travaTimer
        );


        secoes[chave]
          .scrollIntoView({
            behavior:
              "smooth"
          });


        destacar(
          chave
        );


        travaTimer =
          setTimeout(
            () => {

              travado =
                false;

              atualizarMenu();

            },
            900
          );

      }

      else if (
        PAGINAS[chave]
      ) {

        a.href =
          PAGINAS[chave];

      }

      else {

        e.preventDefault();

        aviso(
          `"${a.textContent}" é outra página do projeto e ainda não foi ligada a este menu.`
        );

      }

    }
  );


  // ============================================================
  // INFORMATIVOS
  // ============================================================

  const news = [];


  function ago(ts) {

    const m =
      Math.max(
        0,
        Math.round(
          (Date.now() - ts) /
          60000
        )
      );


    if (m < 1)
      return "agora";


    if (m < 60)
      return `há ${m} min`;


    const h =
      Math.floor(
        m / 60
      );


    return h < 24
      ? `há ${h} h`
      : `há ${Math.floor(
          h / 24
        )} d`;

  }


  function renderNews() {

    $("#news").innerHTML =

      [
        ...news
      ]

        .sort(
          (a, b) =>
            b.ts - a.ts
        )

        .slice(0, 6)

        .map(
          (n) =>

            `<li>

              <span class="when">
                ${ago(n.ts)}
              </span>

              <div>

                <span class="t">
                  ${esc(
                    n.titulo
                  )}
                </span>

                ${
                  n.placeholder
                    ? '<span class="ex">EXEMPLO</span>'
                    : ""
                }

                <div class="d">
                  ${esc(
                    n.texto
                  )}
                </div>

              </div>

            </li>`

        )

        .join("");

  }


  // ============================================================
  // RELÓGIO
